function token(value) {
  return String(value || '').trim().split(':', 1)[0];
}
export function normalizeGeneratedErrorReason(...values) {
  for (const value of values) {
    const candidate = token(value);
    if (!candidate) continue;
    if (ERROR_REASON_POLICY[candidate]) return candidate;
    const alias = ERROR_REASON_ALIASES[candidate] || ERROR_REASON_ALIASES[candidate.toLowerCase()] || ERROR_REASON_ALIASES[candidate.toUpperCase()];
    if (alias) return alias;
  }
  return 'hook_handler_failed';
}
export function generatedErrorPolicy(reason) {
  return ERROR_REASON_POLICY[reason] || ERROR_REASON_POLICY.hook_handler_failed;
}
